-- Wioślarstwo (klasyczne i plażowe), rugby 7, żeglarstwo, strzelectwo, skateboarding,
-- kajakarstwo (slalomowe i klasyczne) – tablice kwot LA28 i kalendarze. Wioślarstwo i kajakarstwo dostają poddyscypliny.
-- Można uruchomić ponownie. Źródła: systemy kwalifikacji World Rowing, World Rugby, World Sailing, ISSF,
-- World Skate i ICF dla LA28; wyniki Igrzysk Azjatyckich 2026 (żeglarstwo).

insert into public.dyscypliny (slug, nazwa, nadrzedna_id, kolejnosc)
select v.slug, v.nazwa, j.id, v.kol
from (values ('wioslarstwo-klasyczne', 'Wioślarstwo klasyczne', 1), ('wioslarstwo-plazowe', 'Wioślarstwo plażowe', 2)) as v(slug, nazwa, kol)
cross join (select id from public.dyscypliny where slug = 'wioslarstwo') j
on conflict (slug) do update set nadrzedna_id = excluded.nadrzedna_id, nazwa = excluded.nazwa;

insert into public.dyscypliny (slug, nazwa, nadrzedna_id, kolejnosc)
select v.slug, v.nazwa, j.id, v.kol
from (values ('kajakarstwo-slalom', 'Kajakarstwo slalomowe', 1), ('kajakarstwo-klasyczne', 'Kajakarstwo klasyczne', 2)) as v(slug, nazwa, kol)
cross join (select id from public.dyscypliny where slug = 'kajakarstwo') j
on conflict (slug) do update set nadrzedna_id = excluded.nadrzedna_id, nazwa = excluded.nazwa;

update public.dyscypliny set opis_kafla = v.opis from (values
  ('wioslarstwo', 'Wioślarstwo klasyczne i plażowe (beach sprint)'),
