where d.id = t.dyscyplina_id and d.slug in ('wioslarstwo-klasyczne', 'wioslarstwo-plazowe', 'rugby', 'zeglarstwo', 'strzelectwo', 'skateboarding', 'kajakarstwo-slalom', 'kajakarstwo-klasyczne');
